/* ----------------------------------- */
body {
    font-family: 'Arial', sans-serif;
    line-height: 0.5;
    margin: 0;
    padding: 0;
    color: #333;
    background-color: #f0f0f0;
}

.invoice-container {
    max-width: 1200px;
    margin: 10px auto;
    padding: 10px;
    background-color: #fff;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.1);
    border-radius: 8px;
}

/* Header */
.invoice-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 30px;
    padding-bottom: 15px;
    border-bottom: 3px solid #ccc;
}

.company-info {
    display: flex;
    flex-direction: column;
}
.company-logo {
    max-height: 50px;
    width: auto;
    margin-bottom: 8px;
}
.company-name {
    margin: 0;
    font-size: 1.5em;
    color: #000;
}

.doc-title-box {
    text-align: right;
}
.doc-type {
    margin: 0;
    font-size: 2.5em;
    color: #007bff;
    text-transform: uppercase;
    font-weight: 900;
}
.doc-status {
    font-size: 0.9em;
    padding: 3px 8px;
    border-radius: 4px;
    display: inline-block;
    font-weight: bold;
}
.pos-tag { background-color: #e6f7ff; color: #007bff; }
.return-tag { background-color: #fff0f6; color: #ff4d4f; }
.standard-tag { background-color: #f6ffed; color: #52c41a; }

.section-separator {
    border: 0;
    height: 1px;
    background: #eee;
    margin: 0 0 30px 0;
}

/* Details Section (Dates & Customer) */
.details-section {
    display: flex;
    justify-content: space-between;
    padding: 10px 0;
    margin-bottom: 40px;
    border-bottom: 1px solid #ddd;
}
.column {
    flex: 1;
    padding-right: 20px;
}
.detail-label {
    font-size: 0.8em;
    color: #777;
    margin: 0 0 5px 0;
    text-transform: uppercase;
}
.detail-data {
    font-size: 1.1em;
    font-weight: bold;
    color: #000;
    margin: 0;
}

/* Items Table */
.items-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 30px;
}
.items-table th {
    background-color: #f7f7f7;
    color: #555;
    border-bottom: 2px solid #ddd;
    padding: 12px 10px;
    text-align: left;
    font-weight: bold;
    text-transform: uppercase;
    font-size: 0.9em;
}
.items-table td {
    border-bottom: 1px solid #eee;
    padding: 10px;
    font-size: 0.95em;
}
.items-table tbody tr:last-child td {
    border-bottom: none;
}
.align-right {
    text-align: right;
}
.col-sno { width: 5%; text-align: center; }
.col-qty, .col-rate, .col-amount { width: 15%; }

/* Summary Section (Totals and QR) */
.summary-section {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-top: 20px;
}

.in-words-box {
    width: 40%;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}
.in-words {
    font-size: 1em;
    margin-top: 15px;
    border-top: 1px dashed #ccc;
    padding-top: 10px;
}

.totals-col {
    width: 45%;
}
.total-row {
    display: flex;
    justify-content: space-between;
    padding: 5px 0;
}
.total-row .label {
    color: #555;
}
.total-row .value {
    font-weight: bold;
}
.total-row.adjustment {
    font-size: 0.9em;
    color: #888;
}
.total-row.final-total {
    margin-top: 15px;
    padding: 10px 0;
    border-top: 2px solid #000; /* High contrast separation */
    font-size: 1.2em;
    background-color: #f0f0f0;
    padding: 10px;
}
.final-total .label, .final-total .value {
    font-weight: 900;
    color: #000;
}

/* QR Code */
.qr-box {
    text-align: center;
    padding: 10px;
    border: 1px solid #007bff;
    border-radius: 5px;
    background-color: #fff;
}
.qr-code {
    width: 120px;
    height: 120px;
}
.qr-label {
    font-size: 0.8em;
    margin: 5px 0 0 0;
    color: #007bff;
    font-weight: bold;
}

/* Footer */
.invoice-footer {
    text-align: center;
    margin-top: 40px;
    padding-top: 15px;
    border-top: 1px solid #ddd;
    font-size: 0.9em;
    color: #777;
}


/* ----------------------------------- */
/* Print-Specific Styles               */
/* ----------------------------------- */
@media print {

    .invoice-container {
        border: none;
        box-shadow: none;
        margin: 0; 
        padding: 0;
        width: 100%;
    }

    /* Force all text to black for maximum readability and contrast */
    * {
        color: #000 !important;
    }

    /* Essential print property to preserve borders and backgrounds */
    .items-table th, .final-total, .qr-box {
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
    }

    /* High contrast for borders */
    .invoice-header {
        border-bottom: 3px solid #000 !important;
    }

    /* Remove background colors and add borders for definition */
    .doc-status, .items-table th, .final-total {
        background-color: #fff !important;
        border: 1px solid #000 !important;
    }

    /* Table borders for print clarity */
    .items-table th, .items-table td {
        border: 1px solid #000 !important;
        padding: 8px !important;
    }

    /* QR Code Enhancement */
    .qr-box {
        border: 3px solid #000 !important;
        background-color: #fff !important;
    }
}
